begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select has_table('public','employee_work_terms','canonical effective-dated work terms');
select has_table('public','employee_leave_accounts','admin-confirmed leave baseline');
select has_table('public','employee_leave_requests','atomic request reservations');
select has_table('public','employee_leave_ledger','immutable occurrence keys');
select ok(not has_table_privilege('authenticated','public.employee_leave_accounts','SELECT'),'browser cannot enumerate balances');
select ok(not has_table_privilege('authenticated','public.employee_leave_requests','INSERT'),'client cannot bypass request guards');
select ok(not has_table_privilege('authenticated','public.employee_leave_ledger','UPDATE'),'client cannot overwrite accrual');
select ok(not has_function_privilege('anon','public.get_my_leave_context()','EXECUTE'),'no anonymous balance read');
select ok(not has_function_privilege('authenticated','public.private_accrue_employee_leave(uuid)','EXECUTE'),'no client-controlled accrual');
select ok(not has_function_privilege('authenticated','public.private_reconcile_leave_monthly()','EXECUTE'),'only service monthly worker');
select ok(has_function_privilege('service_role','public.private_reconcile_leave_monthly()','EXECUTE'),'internal monthly reconciliation');
select ok(not has_function_privilege('authenticated','public.private_claim_attendance_reminders(uuid,integer)','EXECUTE'),'no token/queue endpoint for clients');
select ok(not has_function_privilege('authenticated','public.private_validate_attendance_reminder(uuid,uuid)','EXECUTE'),'send-time validation internal');
select ok(not has_function_privilege('authenticated','public.private_record_attendance_event_pre572(text,double precision,double precision,double precision)','EXECUTE'),'renamed attendance cannot bypass schedule gate');
select ok((select relrowsecurity from pg_class where oid='public.employee_work_terms'::regclass),'work terms RLS enabled');
select ok((select relrowsecurity from pg_class where oid='public.employee_leave_accounts'::regclass),'leave RLS enabled');
select ok((select not enabled and delay_minutes=5 from public.employee_reminder_policy where singleton),'approved five-minute policy remains disabled');
select is(public.private_claim_attendance_reminders(gen_random_uuid()),'[]'::jsonb,'disabled reminder cannot claim any delivery');
select ok(exists(select 1 from public.role_capability_grants g join public.roles r on r.id=g.role_id where r.code='promotion_lead' and g.capability_code='leave.manage'),'lead receives narrow leave management only');
select ok(not exists(select 1 from public.role_capability_grants g join public.roles r on r.id=g.role_id where r.code='promotion_lead' and g.capability_code='employee.work_terms_manage'),'leave approval does not confer personnel edit permission');
select ok(not has_function_privilege('authenticated','public.private_request_attendance_exception_pre572(text,text,double precision,double precision,double precision)','EXECUTE'),'old exception cannot bypass schedule gate');
select ok(not has_function_privilege('authenticated','public.private_set_attendance_day_status_pre572(uuid,date,text,text,text)','EXECUTE'),'old day status cannot bypass leave source protection');
select ok(not has_table_privilege('authenticated','public.employee_work_overrides','UPDATE'),'date exceptions cannot be directly overwritten');
select ok(not has_function_privilege('authenticated','public.private_attendance_reminder_due(uuid,date,text,timestamptz)','EXECUTE'),'clients cannot override reminder evaluation time');
select * from finish();
rollback;
